import React, { useEffect, useState } from "react";
import axios from "axios";

export default function Dashboard() {
  const [dashboard, setDashboard] = useState([]);

  useEffect(() => {
    axios
      .get("http://localhost:5000/api/v1/analytics/dashboard")
      .then((res) => {
        console.log(res.data);
         setDashboard(res.data.data[0]);
      })
      .catch((err) => {
        console.error(err);
      });
  }, []);

  return (
    <div>
      <h2>Dashboard</h2>
      <h2>Total Customers: {dashboard.total_customers}</h2>
<h2>Total Products: {dashboard.total_products}</h2>
<h2>Total Orders: {dashboard.total_orders}</h2>
<h2>Total Revenue: ₹{dashboard.total_revenue}</h2>
    </div>
  );
}
